#include <stdio.h>
void main()
{
int i, j, temp, arr_num[5] = { 23, 90, 9, 25, 16};
clrscr();
for(i=3;i>=0;i--) /* Tracks every pass */
for(j=4;j>=4-i;j--) /* Compares elements */
{ if(arr_num[j]<arr_num[j-1])
{ temp=arr_num[j];
arr_num[j]=arr_num[j-1];
arr_num[j-1]=temp;
}
} Contd…..
